const input = $input.first().json;
const rows = (input.rows || []).map(r => {
  const f = r.f || [];
  return {
    customer_uid: f[0]?.v,
    alert_id: f[1]?.v,
    entry_date: f[2]?.v,
    alert_name: f[3]?.v,
    alert_type: f[4]?.v,
    target_module: f[5]?.v,
    trigger_basis: f[6]?.v,
    reference_value: f[7]?.v,
    lead_days: f[8]?.v,
    frequency: f[9]?.v,
    email_enabled: f[10]?.v,
    telegram_enabled: f[11]?.v,
    telegram_chat_id: f[12]?.v,
    status: f[13]?.v,
    last_sent_at: f[14]?.v,
    notes: f[15]?.v
  };
});

const usersMap = {};
for (const row of rows) {
  const email = row.customer_uid === "QLqAWYQ6QUTlb52HpZ89Ga04Vv03" ? "arusamy71053@gmail.com" : (row.user_id || "arusamy71053@gmail.com");
  if (!usersMap[email]) {
    usersMap[email] = {
      email: email,
      user_name: "Wealthyo Owner",
      alerts: []
    };
  }
  if (row.alert_name) {
    usersMap[email].alerts.push(row);
  }
}

return Object.values(usersMap).map(userData => {
  const alertItems = userData.alerts;
  let alertRowsHtml = alertItems.map(a => 
    "<tr style='border-bottom: 1px solid rgba(255,255,255,0.1);'><td style='padding: 12px; color: #ffd700; font-weight: 700;'>" + a.alert_name + "</td><td style='padding: 12px; color: #cbd5e1;'>" + a.target_module + "</td><td style='padding: 12px; color: #00ff88; font-weight: 700;'>" + a.reference_value + "</td><td style='padding: 12px; color: #94a3b8;'>" + a.frequency + "</td></tr>"
  ).join("");

  const htmlBody = "<html><body style='background-color:#060a12;color:#f4efe4;font-family:sans-serif;padding:24px;'><div style='max-width:640px;margin:0 auto;background:#0f172a;border:2px solid #c9a84c;border-radius:24px;padding:32px;'><div style='text-align:center;border-bottom:1px solid rgba(201,168,76,0.3);padding-bottom:20px;margin-bottom:24px;'><span style='background:rgba(0,255,136,0.16);color:#00ff88;border:1px solid rgba(0,255,136,0.4);padding:4px 12px;border-radius:99px;font-size:11px;font-weight:800;'>⚡ 10-MIN RECURRING BATCH PULSE</span><h1 style='color:#ffd700;font-size:26px;margin:10px 0 4px;'>Executive Portfolio &amp; Alert Overview</h1></div><p style='font-size:14px;'>Hello <strong>" + userData.user_name + "</strong>,</p><table style='width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;'><thead><tr style='background:rgba(255,255,255,0.06);color:#94a3b8;'><th style='padding:10px;'>Alert Rule</th><th style='padding:10px;'>Module</th><th style='padding:10px;'>Trigger / Due</th><th style='padding:10px;'>Frequency</th></tr></thead><tbody>" + alertRowsHtml + "</tbody></table><div style='text-align:center;margin-top:24px;'><a href='https://wealthyo.web.app/dashboard' style='background:linear-gradient(135deg,#ffd700,#f59e0b);color:#060a12;font-weight:900;padding:12px 28px;border-radius:14px;display:inline-block;'>Open Dashboard ↗</a></div></div></body></html>";

  return {
    json: {
      from: "Wealthyo Alerts <alerts@wealthyo.in>",
      to: userData.email,
      subject: "[10-MIN PULSE] ⚡ Wealthyo Portfolio Alert Digest",
      html: htmlBody
    }
  };
});
